  "concerns": [
    {
      "title": "Missing Bank Statement Months (March & April 2026)",
      "claim": "The bank statement D01 has 4 pages covering January, February, May, and June 2026, omitting March and April 2026 completely.",
      "severity": "critical"
    },
    {
      "title": "Declining Revenue Trend",
      "claim": "Gross revenue reported in the ledger decreased continuously from PHP 78,400 in January 2026 to PHP 46,200 in June 2026, representing a 41% drop.",
      "severity": "high"
    },
    {
      "title": "High Existing Debt Service Ratio",
      "claim": "Monthly BDO auto loan amortization of PHP 14,800 consumes a substantial portion of net monthly earnings (net income of PHP 36,950 in June 2026).",
      "severity": "medium"
    },
    {
      "title": "Duplicate / Conflicting Ledger Page",
      "claim": "Document D07 is an identical copy of the March ledger entries (D04) despite bearing the heading 'Abril 2026'.",
      "severity": "medium"
    }
  ]
